    L[bel[n]] = R[bel[n] - 1] + 1, R[bel[n]] = n, sort(q + 1, q + 1 + m);
    for (ri k = 1, i = 1, l, r, p; k <= bel[n]; ++k) {
        l = L[k], r = n, p = s;
        for (ri t; bel[q[i].l] == k; ++i) {
