                ri t = 0;
                for (ri j = q[i].l; j <= q[i].r; ++j) if (a[j] <= n + 1) ++tmp[a[j]];
                while (tmp[t]) ++t;
                ans[q[i].id] = t;
                for (ri j = q[i].l; j <= q[i].r; ++j) if (a[j] <= n + 1) --tmp[a[j]];
