 ins(1,1,n,i,i,la);
 }
 la=1;
 for(i=1;i<=m;i++){
 while(la<aa[i].x)ins(1,1,n,la+1,nt[la]-1,a[la]),la++;
 ans[aa[i].id]=query(1,1,n,aa[i].y);
 }
 for(i=1;i<=m;i++)printf("%d\n",ans[i]);
}

